def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Strong punishment for defection, mild reward for cooperation
    if observation['action'] == 'A':
        return min(1.0, current_reputation + 0.1)
    else:
        return max(-1.0, current_reputation - 0.5)

def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Cooperate only if recipient has very high reputation
    return recipient_reputation > 0.5

def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Milder reputation update: reward cooperation more, punish defection less
    if observation['action'] == 'A':
        new_rep = current_reputation + 0.2
    else:
        new_rep = current_reputation - 0.3
    return max(-1.0, min(1.0, new_rep))

def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Only cooperate if reputation is positive and we've played enough rounds
    # This adds a weak initial "exploration" phase
    threshold = 0.2
    if round_num <= 3:
        return False
    return recipient_reputation > threshold
